// València's trees in the detailed city, generated by tools/realism/build-trees.py from the municipal tree inventory
// (Ajuntament de València, Arbratge / Arbolado, CC BY 4.0): VLT1 (gzipped) = magic, count, then 8-byte records
// [i16 x, i16 z (world, 0.25 m units), u8 species (trees.js: 0 plane, 1 locust, 2 elm, 3 palm, 4 bitter orange),
//  u8 scale x 50, u8 flags (1: in a sidewalk pit), u8 yaw (256ths of a turn)].
const response = await fetch(new URL('./vlc-trees.bin.gz', import.meta.url));
if (!response.ok) throw new Error(`Tree data request failed: ${response.status}`);
const body = new Uint8Array(await response.arrayBuffer());
const data = body[0] === 0x1f && body[1] === 0x8b
  ? new Uint8Array(await new Response(new Response(body).body.pipeThrough(new DecompressionStream('gzip'))).arrayBuffer())
  : body;
if (String.fromCharCode(...data.subarray(0, 4)) !== 'VLT1') throw new Error('Invalid tree data.');
const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
const count = view.getUint32(4, true);
const trees = [];
for (let i = 0, o = 8; i < count; i++, o += 8) {
  trees.push({
    x: view.getInt16(o, true) / 4,
    z: view.getInt16(o + 2, true) / 4,
    species: data[o + 4],
    scale: data[o + 5] / 50,
    pit: (data[o + 6] & 1) === 1,
    yaw: (data[o + 7] / 256) * Math.PI * 2
  });
}

export const REAL_TREES = trees;
